fail() { echo "VERIFY FAIL $*"; exit 1; }
count() { wc -l | tr -d ' '; }
# exact names: the sorted list of every path under the root, compared by cksum
names() { find . -mindepth 1 "$@" | LC_ALL=C sort | cksum; }
[ "$(names )" = "$({ for i in $(seq 1 1000); do echo ./f$i; done; } | LC_ALL=C sort | cksum)" ] || fail "names: $(find . -mindepth 1  | count) entries; unexpected: $(find . -mindepth 1  | grep -v -E '^[.]/(f[0-9]+|[0-9]+(/[0-9]+)*|big2?)$' | head -5 | tr '\n' ' ')"
[ "$(find . -mindepth 1 -path ./.git -prune -o ! -type f -print | count)" = 0 ] || fail "an entry other than a regular file"
[ "$(cat $(seq 1 1000 | sed 's/^/f/') | cksum)" = "$(seq 1 1000 | cksum)" ] || fail "f1..f1000 contents"
wc -c $(seq 1 1000 | sed 's/^/f/') | awk '$2 != "total" && $1 != length(substr($2, 2)) + 1 { print "size", $2; bad = 1 } END { exit bad }' || fail "a file of the wrong size"
echo "VERIFY OK"

