fail() { echo "VERIFY FAIL $*"; exit 1; }
count() { wc -l | tr -d ' '; }
# exact names: the sorted list of every path under the root, compared by cksum
names() { find . -mindepth 1 "$@" | LC_ALL=C sort | cksum; }
